package org.springframework.samples.petclinic.rest.function.owner;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.time.temporal.TemporalAdjusters;
import java.util.List;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.MissingFieldsException;

public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built)
            throws MissingFieldsException {
        Owner owner = ownerMapper.toOwner(request);
        LocalDate supplied = owner.getRegistrationDate();
        if (supplied != null && supplied.isAfter(LocalDate.now())) { // future date: reject as 400
            throw new MissingFieldsException(List.of("registrationDate"));
        }
        LocalDate date = supplied != null ? supplied : LocalDate.now();
        if (date.getDayOfWeek().getValue() > 5) { // Saturday or Sunday: roll forward to Monday
            date = date.with(TemporalAdjusters.next(DayOfWeek.MONDAY));
        }
        owner.setRegistrationDate(date);
        built.set(owner);
    }
}
===== IdentityKey =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives an owner's {@code identityKey} = normalized telephone + '|' + (lower-cased email or
 * empty) + '|' + household id. Duplicate detection is a single equality on this whole key, and it
 * is also returned on the owner. Two owners collide only when telephone, email and household all
 * match; sharing only a household (with different telephones) yields different keys.
 */
public final class IdentityKey {

    private IdentityKey() {
    }

    public static String of(Owner owner) {
        String email = owner.getEmail() == null || owner.getEmail().isBlank()
                ? "" : owner.getEmail().toLowerCase(Locale.ROOT);
        return owner.getTelephone() + "|" + email + "|" + owner.getHouseholdId();
    }
}

